window.AUTH=window.AUTH||{};window.AUTH["02-337"]={"d":"02-337","id":"2002/02-337","n":"Breuer v. Jim's Concrete of Brevard, Inc.","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/193461/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/breuer-v-jims-concrete-brevard-amicus-merits","n":82}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep538/usrep538691/usrep538691.pdf","tr":false,"items":[{"t":"case","label":"American Fin. Co. v. Bostwick","cite":"23 N.E. 656","y":1890,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./23/656/","by":{"0":"19"}},{"t":"case","label":"Anson v. University of Tex. Health Sci. Ctr.","cite":"962 F.2d 539","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/962/539/","by":{"0":"19"}},{"t":"case","label":"Avco Corp. v. Aero Lodge","cite":"390 U.S. 557","y":1968,"id":"1967/445","sc":1,"sum":"Petitioner, employer, brought suit in a Tennessee court to enjoin respondent union and its members from striking in violation of a \"no-strike\" clause in the collective bargaining agreement. The state court issued an ex parte injunction. Respondents moved in Federal District Court for removal of the case, and dissolution of the injunction. The District Court ruled that the action was within its original jurisdiction, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Bay Area Laundry & Dry Cleaning Pension Trust Fund v. Ferbar Corp.","cite":"522 U.S. 192","y":1997,"id":"1997/96-370","sc":1,"sum":"The Court held that the MPPAA's six-year statute of limitations on a pension fund's action to collect unpaid withdrawal liability does not begin to run until the employer fails to make a payment on the schedule set by the fund.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Boys Mkts., Inc. v. Retail Clerks Union","cite":"398 U.S. 235","y":1970,"id":"1969/768","sc":1,"sum":"In the circumstances of this case-where the grievance was subject to arbitration under the collectivebargaining agreement, petitioner was ready for arbitration when the strike was enjoined, and the District Court concluded that respondent's violations of the no-strike clause were causing petitioner irreparable injury--the Norris-LaGuardia Act does not bar the granting of injunctive relief. Sinclair Refining Co. v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Colorado River Water Conservation Dist. v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23"}},{"t":"case","label":"Cosme Nieves v. Deshler","cite":"786 F.2d 445","y":1986,"url":"https://www.courtlistener.com/c/F.2d/786/445/","op":2,"by":{"0":"3, 9"}},{"t":"case","label":"Crawford Fitting Co. v. J.T. Gibbons, Inc.","cite":"482 U.S. 437","y":1987,"id":"1986/86-322","sc":1,"sum":"When a prevailing party seeks reimbursement for fees paid to its expert witnesses, a federal court is bound by the limits of § 1821(b), absent contract or explicit statutory authority to the contrary. There is no merit to petitioners' contentions that, since § 1920 lists expenses which a court \"may\" tax as costs, it only authorizes taxation of such items and does not preclude taxation for other items or amounts in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Custis v. United States","cite":"511 U.S. 485","y":1994,"id":"1993/93-5209","sc":1,"sum":"After the jury convicted petitioner Custis of possession of a firearm by a felon and another federal crime, the Government relied on his prior state-court convictions for robbery in Pennsylvania and for burglary and attempted burglary in Maryland to support a motion under the Armed Career Criminal Act of 1984, 18 U. S. C. § 924(e) (ACCA), which provides for enhancement of the sentence of a convicted firearms …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Estate of Cowart v. Nicklos Drilling Co.","cite":"505 U.S. 469","y":1992,"id":"1991/91-17","sc":1,"sum":"Section 33(g)'s forfeiture provision applies to a worker whose employer, at the time the worker settles with a third party, is neither paying compensation to the worker nor subject to an order to pay under the Act. The section's language is plain and cannot support the BRB's interpretation. The normal meaning of entitlement includes a right or benefit for which a person qualifies, regardless of whether the right or …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"George Moore Ice Cream Co. v. Rose","cite":"289 U.S. 373","y":1933,"id":"scdb/1932-082","sc":1,"sum":"OCrOBER TERM, 1932. Counsel for Parties. 289 US. (1) That the former rule requiring a protest at the time of payment, as a condition precedent to recovery, is abolished as to any suit brought after the date of the Act, irrespective of the date of the underlying payment. P. 375. (2) This view results from the phraseology and implications of the statute, and is confirmed by its history and congressional reports.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12"}},{"t":"case","label":"Gregory v. Ashcroft","cite":"501 U.S. 452","y":1991,"id":"1990/90-50","sc":1,"sum":"In addition to emphasizing Missouri's, or any other state's, Tenth Amendment right to define the qualifications of its highest state officials, the Court held that the regulations of the ADEA did not apply to \"policy-making\" appointees such as state court judges.","sumSrc":"Oyez","by":{"0":"11"}},{"t":"case","label":"Hill v. Moss-American, Inc.","cite":"309 F. Supp. 1175","y":1970,"court":"N.D. Miss.","url":"https://www.courtlistener.com/c/F.%20Supp./309/1175/","by":{"0":"8, 26"}},{"t":"case","label":"Hirschbiel v. Johnson","cite":"118 F. Supp. 2d 903","y":2000,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/118/903/","by":{"0":"27"}},{"t":"case","label":"Hoffmann-La Roche Inc. v. Sperling","cite":"493 U.S. 165","y":1989,"id":"1989/88-1203","sc":1,"sum":"District courts have discretion, in appropriate cases, to implement § 216(b), as incorporated by § 626(b), in ADEA actions by facilitating notice to potential plaintiffs. However, as did the Court of Appeals, this Court declines to examine the terms of the notice used here.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 19"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Johnson v. Butler Bros.","cite":"162 F.2d 87","y":1947,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/162/87/","op":2,"by":{"0":"27"}},{"t":"case","label":"Lewis v. Lewis & Clark Marine, Inc.","cite":"531 U.S. 438","y":2001,"id":"2000/99-1331","sc":1,"sum":"The Court held that because state courts may adjudicate claims like Lewis' against vessel owners so long as the owner's right to seek limitation of liability is protected, the Court of Appeals erred in reversing the District Court's decision to dissolve the injunction.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Metropolitan Life Ins. Co. v. Taylor","cite":"481 U.S. 58","y":1987,"id":"1986/85-686","sc":1,"sum":"Section 502(a)(1)(B) of the Employee Retirement Income Security Act of 1974 (ERISA) provides that a participant or beneficiary may bring a civil action to, inter alia, recover benefits due him under the terms of an employee benefit plan. Under 28 U. S. C. § 1441(a), any civil action brought in state court of which the federal district courts have original jurisdiction may be removed by the defendant to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"O’Connell v. Champion Int’l Corp.","cite":"812 F.2d 393","y":1987,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/812/393/","by":{"0":"20"}},{"t":"case","label":"Palmore v. United States","cite":"411 U.S. 389","y":1973,"id":"1972/72-11","sc":1,"sum":"1 1. The District of Columbia Code is not a state statute for purposes of § 1257 (2), and the lower court's upholding of the federal statute is therefore not reviewable by appeal but by certiorari.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Red Rock v. Henry","cite":"106 U.S. 596","y":1883,"id":"scdb/1882-088","sc":1,"sum":"The legislature of the State of Minnesota, on March 6, 1868, passed an act entitled “ An Act to authorize the towns in Fillmore, Mower, Freeborn, Faribault, Martin, and Jackson Counties to issue bonds to aid in the construction of any railroad running into or through said counties.” The first three sections of the act, the only ones material to this case, are as follows: —","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Ruckelshaus v. Monsanto Co.","cite":"467 U.S. 986","y":1984,"id":"1983/83-196","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) authorizes the Environmental Protection Agency (EPA) to use data submitted by an applicant for registration of a covered product (hereinafter pesticide) in evaluating the application of a subsequent applicant, and to disclose publicly some of the submitted data. Under the dataconsideration provisions of § 3, as amended in 1978, applicants now are …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Shamrock Oil & Gas Corp. v. Sheets","cite":"313 U.S. 100","y":1941,"id":"scdb/1940-150","sc":1,"op":3,"sum":"1, Removability of suits from state to federal courts is determined by the federal removal statute, unaffected by local law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Smallwood v. Gallardo","cite":"275 U.S. 56","y":1927,"id":"scdb/1927-001","sc":1,"op":1,"sum":"1. To “ maintain ” a suit is to uphold, continue on foot and keep from collapse a suit already begun. P.' 61.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"12, 18"}},{"t":"case","label":"TVA v. Hill","cite":"437 U.S. 153","y":1978,"id":"1977/76-1701","sc":1,"sum":"The Supreme Court held that Congress’ continued appropriation of funds did not imply that the Dam project was exempt from the ESA. The operation of the Tellico Dam would wipe out the Snail Darter's habitat, so an injunction was the proper remedy.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"sum":"It is not clear from the language and legislative history of § 1202 (a) (1) whether or not receipt or possession of a firearm by a convicted felon has to be shown in an individual prosecution to have been connected with interstate commerce. The ambiguity of this provision (which is not only a criminal statute but one whose broad construction would define as a federal offense conduct readily proscribed by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"United States v. Monsanto","cite":"491 U.S. 600","y":1989,"id":"1988/88-454","sc":1,"sum":"Respondent, who allegedly directed a large-scale heroin distribution enterprise, was indicted for alleged violations of racketeering laws, creation of a continuing criminal enterprise, and tax and firearm offenses. The indictment also alleged that respondent had accumulated three specified assets as a result of his narcotics trafficking, which were subject to forfeiture under the Comprehensive Forfeiture Act of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Providence Journal Co.","cite":"485 U.S. 693","y":1988,"id":"1987/87-65","sc":1,"sum":"Since the special prosecutor lacks authority to represent the United States before this Court, the writ of certiorari is dismissed for want of jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"United States v. Shabani","cite":"513 U.S. 10","y":1994,"id":"1994/93-981","sc":1,"sum":"In order to establish a violation of §846, the Government need not prove the commission of any overt acts in furtherance of the conspiracy. The statute's plain language does not require an overt act, and such a requirement has not been inferred from congressional silence in other conspiracy statutes, see, e. g., Nash v. United States, 229 U. S. 373. Thus, absent contrary indications, it is presumed that Congress …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Williams v. Jacksonville Terminal Co.","cite":"315 U.S. 386","y":1942,"id":"scdb/1941-037","sc":1,"sum":"The Fair Labor Standards Act of 1938 requires employers to pay to every employee engaged in interstate commerce not less than the prescribed minimum hourly wage. When the Act became effective, the respondent terminal companies gave notice to redcaps in their employ of the establishment of a so-called accounting and guarantee system, whereby each redcap was required to account for the tips he received and was …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"usc","label":"16 U.S.C. § 416","url":"https://www.law.cornell.edu/uscode/text/16/416","by":{"0":"10, 11"}},{"t":"usc","label":"45 U.S.C. § 56","url":"https://www.law.cornell.edu/uscode/text/45/56","by":{"0":"11, 14"}},{"t":"usc","label":"28 U.S.C. § 71","url":"https://www.law.cornell.edu/uscode/text/28/71","subs":["(1934)"],"by":{"0":"4, 14, 21"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","subs":["(b)"],"by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1337","url":"https://www.law.cornell.edu/uscode/text/28/1337","by":{"0":"3-4, 5"}},{"t":"usc","label":"28 U.S.C. § 1404","url":"https://www.law.cornell.edu/uscode/text/28/1404","stext":{"head":"§1404. Change of venue","paras":[[0,"(a) For the convenience of parties and witnesses, in the interest of justice, a district court may transfer any civil action to any other district or division where it might have been brought or to any district or division to which all parties have consented."],[0,"(b) Upon motion, consent or stipulation of all parties, any action, suit or proceeding of a civil nature or any motion or hearing thereof, may be transferred, in the discretion of the court, from the division in which pending to any other division in the same district. Transfer of proceedings in rem brought by or on behalf of the United States may be transferred under this section without the consent of the United States where all other parties request transfer."],[0,"(c) A district court may order any civil action to be tried at any place within the division in which it is pending."],[0,"(d) Transfers from a district court of the United States to the District Court of Guam, the District Court for the Northern Mariana Islands, or the District Court of the Virgin Islands shall not be permitted under this section. As otherwise used in this section, the term \"district court\" includes the District Court of Guam, the District Court for the Northern Mariana Islands, and the District Court of the Virgin Islands, and the term \"district\" includes the territorial jurisdiction of each such court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1404?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1404. Change of venue","tname":"Judiciary and Judicial Procedure","by":{"0":"13"}},{"t":"usc","label":"28 U.S.C. § 1441","url":"https://www.law.cornell.edu/uscode/text/28/1441","subs":["(a)","(b)"],"stext":{"head":"§1441. Removal of civil actions","paras":[[0,"(a) Generally.—Except as otherwise expressly provided by Act of Congress, any civil action brought in a State court of which the district courts of the United States have original jurisdiction, may be removed by the defendant or the defendants, to the district court of the United States for the district and division embracing the place where such action is pending."],[0,"(b) Removal Based on Diversity of Citizenship.—(1) In determining whether a civil action is removable on the basis of the jurisdiction under section 1332(a) of this title, the citizenship of defendants sued under fictitious names shall be disregarded."],[0,"(2) A civil action otherwise removable solely on the basis of the jurisdiction under section 1332(a) of this title may not be removed if any of the parties in interest properly joined and served as defendants is a citizen of the State in which such action is brought."],[0,"(c) Joinder of Federal Law Claims and State Law Claims.—(1) If a civil action includes—"],[1,"(A) a claim arising under the Constitution, laws, or treaties of the United States (within the meaning of section 1331 of this title), and"],[1,"(B) a claim not within the original or supplemental jurisdiction of the district court or a claim that has been made nonremovable by statute,"],[0,"the entire action may be removed if the action would be removable without the inclusion of the claim described in subparagraph (B)."],[0,"(2) Upon removal of an action described in paragraph (1), the district court shall sever from the action all claims described in paragraph (1)(B) and shall remand the severed claims to the State court from which the action was removed. Only defendants against whom a claim described in paragraph (1)(A) has been asserted are required to join in or consent to the removal under paragraph (1)."],[0,"(d) Actions Against Foreign States.—Any civil action brought in a State court against a foreign state as defined in section 1603(a) of this title may be removed by the foreign state to the district court of the United States for the district and division embracing the place where such action is pending. Upon removal the action shall be tried by the court without jury. Where removal is based upon this subsection, the time limitations of section 1446(b) of this chapter may be enlarged at any time for cause shown."],[0,"(e) Multiparty, Multiforum Jurisdiction.—(1) Notwithstanding the provisions of subsection (b) of this section, a defendant in a civil action in a State court may remove the action to the district court of the United States for the district and division embracing the place where the action is pending if—"],[1,"(A) the action could have been brought in a United States district court under section 1369 of this title; or"],[1,"(B) the defendant is a party to an action which is or could have been brought, in whole or in part, under section 1369 in a United States district court and arises from the same accident as the action in State court, even if the action to be removed could not have been brought in a district court as an original matter."],[0,"The removal of an action under this subsection shall be made in accordance with section 1446 of this title, except that a notice of removal may also be filed before trial of the action in State court within 30 days after the date on which the defendant first becomes a party to an action under section 1369 in a United States district court that arises from the same accident as the action in State court, or at a later time with leave of the district court."],[0,"(2) Whenever an action is removed under this subsection and the district court to which it is removed or transferred under section 1407(j) 1 has made a liability determination requiring further proceedings as to damages, the district court shall remand the action to the State court from which it had been removed for the determination of damages, unless the court finds that, for the convenience of parties and witnesses and in the interest of justice, the action should be retained for the determination of damages."],[0,"(3) Any remand under paragraph (2) shall not be effective until 60 days after the district court has issued an order determining liability and has certified its intention to remand the removed action for the determination of damages. An appeal with respect to the liability determination of the district court may be taken during that 60-day period to the court of appeals with appellate jurisdiction over the district court. In the event a party files such an appeal, the remand shall not be effective until the appeal has been finally disposed of. Once the remand has become effective, the liability determination shall not be subject to further review by appeal or otherwise."],[0,"(4) Any decision under this subsection concerning remand for the determination of damages shall not be reviewable by appeal or otherwise."],[0,"(5) An action removed under this subsection shall be deemed to be an action under section 1369 and an action in which jurisdiction is based on section 1369 of this title for purposes of this section and sections 1407, 1697, and 1785 of this title."],[0,"(6) Nothing in this subsection shall restrict the authority of the district court to transfer or dismiss an action on the ground of inconvenient forum."],[0,"(f) Derivative Removal Jurisdiction.—The court to which a civil action is removed under this section is not precluded from hearing and determining any claim in such civil action because the State court from which such civil action is removed did not have jurisdiction over that claim."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1441?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1441. Removal of civil actions","tname":"Judiciary and Judicial Procedure","by":{"0":"3, 5, 6, 15, passim, 28"}},{"t":"usc","label":"28 U.S.C. § 1445","url":"https://www.law.cornell.edu/uscode/text/28/1445","subs":["(b)","(c)"],"stext":{"head":"§1445. Nonremovable actions","paras":[[0,"(a) A civil action in any State court against a railroad or its receivers or trustees, arising under sections 1–4 and 5–10 of the Act of April 22, 1908 (45 U.S.C. 51–54, 55–60), may not be removed to any district court of the United States."],[0,"(b) A civil action in any State court against a carrier or its receivers or trustees to recover damages for delay, loss, or injury of shipments, arising under section 11706 or 14706 of title 49, may not be removed to any district court of the United States unless the matter in controversy exceeds $10,000, exclusive of interest and costs."],[0,"(c) A civil action in any State court arising under the workmen's compensation laws of such State may not be removed to any district court of the United States."],[0,"(d) A civil action in any State court arising under section 40302 of the Violence Against Women Act of 1994 may not be removed to any district court of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1445?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1445. Nonremovable actions","tname":"Judiciary and Judicial Procedure","by":{"0":"7, 14, 7, 25, 26"}},{"t":"usc","label":"28 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/28/1446","subs":["(a)"],"by":{"0":"13"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 626","url":"https://www.law.cornell.edu/uscode/text/29/626","subs":["(c)"],"stext":{"head":"§626. Recordkeeping, investigation, and enforcement","paras":[[0,"(a) Attendance of witnesses; investigations, inspections, records, and homework regulations"],[0,"The Equal Employment Opportunity Commission shall have the power to make investigations and require the keeping of records necessary or appropriate for the administration of this chapter in accordance with the powers and procedures provided in sections 209 and 211 of this title."],[0,"(b) Enforcement; prohibition of age discrimination under fair labor standards; unpaid minimum wages and unpaid overtime compensation; liquidated damages; judicial relief; conciliation, conference, and persuasion"],[0,"The provisions of this chapter shall be enforced in accordance with the powers, remedies, and procedures provided in sections 211(b), 216 (except for subsection (a) thereof), and 217 of this title, and subsection (c) of this section. Any act prohibited under section 623 of this title shall be deemed to be a prohibited act under section 215 of this title. Amounts owing to a person as a result of a violation of this chapter shall be deemed to be unpaid minimum wages or unpaid overtime compensation for purposes of sections 216 and 217 of this title: Provided, That liquidated damages shall be payable only in cases of willful violations of this chapter. In any action brought to enforce this chapter the court shall have jurisdiction to grant such legal or equitable relief as may be appropriate to effectuate the purposes of this chapter, including without limitation judgments compelling employment, reinstatement or promotion, or enforcing the liability for amounts deemed to be unpaid minimum wages or unpaid overtime compensation under this section. Before instituting any action under this section, the Equal Employment Opportunity Commission shall attempt to eliminate the discriminatory practice or practices alleged, and to effect voluntary compliance with the requirements of this chapter through informal methods of conciliation, conference, and persuasion."],[0,"(c) Civil actions; persons aggrieved; jurisdiction; judicial relief; termination of individual action upon commencement of action by Commission; jury trial"],[0,"(1) Any person aggrieved may bring a civil action in any court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter: Provided, That the right of any person to bring such action shall terminate upon the commencement of an action by the Equal Employment Opportunity Commission to enforce the right of such employee under this chapter."],[0,"(2) In an action brought under paragraph (1), a person shall be entitled to a trial by jury of any issue of fact in any such action for recovery of amounts owing as a result of a violation of this chapter, regardless of whether equitable relief is sought by any party in such action."],[0,"(d) Filing of charge with Commission; timeliness; conciliation, conference, and persuasion; unlawful practice"],[0,"(1) No civil action may be commenced by an individual under this section until 60 days after a charge alleging unlawful discrimination has been filed with the Equal Employment Opportunity Commission. Such a charge shall be filed—"],[1,"(A) within 180 days after the alleged unlawful practice occurred; or"],[1,"(B) in a case to which section 633(b) of this title applies, within 300 days after the alleged unlawful practice occurred, or within 30 days after receipt by the individual of notice of termination of proceedings under State law, whichever is earlier."],[0,"(2) Upon receiving such a charge, the Commission shall promptly notify all persons named in such charge as prospective defendants in the action and shall promptly seek to eliminate any alleged unlawful practice by informal methods of conciliation, conference, and persuasion."],[0,"(3) For purposes of this section, an unlawful practice occurs, with respect to discrimination in compensation in violation of this chapter, when a discriminatory compensation decision or other practice is adopted, when a person becomes subject to a discriminatory compensation decision or other practice, or when a person is affected by application of a discriminatory compensation decision or other practice, including each time wages, benefits, or other compensation is paid, resulting in whole or in part from such a decision or other practice."],[0,"(e) Reliance on administrative rulings; notice of dismissal or termination; civil action after receipt of notice"],[0,"Section 259 of this title shall apply to actions under this chapter. If a charge filed with the Commission under this chapter is dismissed or the proceedings of the Commission are otherwise terminated by the Commission, the Commission shall notify the person aggrieved. A civil action may be brought under this section by a person defined in section 630(a) of this title against the respondent named in the charge within 90 days after the date of the receipt of such notice."],[0,"(f) Waiver"],[0,"(1) An individual may not waive any right or claim under this chapter unless the waiver is knowing and voluntary. Except as provided in paragraph (2), a waiver may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) the waiver is part of an agreement between the individual and the employer that is written in a manner calculated to be understood by such individual, or by the average individual eligible to participate;"],[1,"(B) the waiver specifically refers to rights or claims arising under this chapter;"],[1,"(C) the individual does not waive rights or claims that may arise after the date the waiver is executed;"],[1,"(D) the individual waives rights or claims only in exchange for consideration in addition to anything of value to which the individual already is entitled;"],[1,"(E) the individual is advised in writing to consult with an attorney prior to executing the agreement;"],[1,"(F)(i) the individual is given a period of at least 21 days within which to consider the agreement; or"],[1,"(ii) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the individual is given a period of at least 45 days within which to consider the agreement;"],[1,"(G) the agreement provides that for a period of at least 7 days following the execution of such agreement, the individual may revoke the agreement, and the agreement shall not become effective or enforceable until the revocation period has expired;"],[1,"(H) if a waiver is requested in connection with an exit incentive or other employment termination program offered to a group or class of employees, the employer (at the commencement of the period specified in subparagraph (F)) informs the individual in writing in a manner calculated to be understood by the average individual eligible to participate, as to—"],[2,"(i) any class, unit, or group of individuals covered by such program, any eligibility factors for such program, and any time limits applicable to such program; and"],[2,"(ii) the job titles and ages of all individuals eligible or selected for the program, and the ages of all individuals in the same job classification or organizational unit who are not eligible or selected for the program."],[0,"(2) A waiver in settlement of a charge filed with the Equal Employment Opportunity Commission, or an action filed in court by the individual or the individual's representative, alleging age discrimination of a kind prohibited under section 623 or 633a of this title may not be considered knowing and voluntary unless at a minimum—"],[1,"(A) subparagraphs (A) through (E) of paragraph (1) have been met; and"],[1,"(B) the individual is given a reasonable period of time within which to consider the settlement agreement."],[0,"(3) In any dispute that may arise over whether any of the requirements, conditions, and circumstances set forth in subparagraph (A), (B), (C), (D), (E), (F), (G), or (H) of paragraph (1), or subparagraph (A) or (B) of paragraph (2), have been met, the party asserting the validity of a waiver shall have the burden of proving in a court of competent jurisdiction that a waiver was knowing and voluntary pursuant to paragraph (1) or (2)."],[0,"(4) No waiver agreement may affect the Commission's rights and responsibilities to enforce this chapter. No waiver may be used to justify interfering with the protected right of an employee to file a charge or participate in an investigation or proceeding conducted by the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/626?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§626. Recordkeeping, investigation, and enforcement","tname":"Labor","by":{"0":"27"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","by":{"0":"27"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","by":{"0":"27"}},{"t":"usc","label":"29 U.S.C. § 2005","url":"https://www.law.cornell.edu/uscode/text/29/2005","subs":["(c)(2)"],"by":{"0":"27"}},{"t":"usc","label":"29 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/29/1001","by":{"0":"27"}},{"t":"usc","label":"29 U.S.C. § 1132","url":"https://www.law.cornell.edu/uscode/text/29/1132","subs":["(a)(1)(B)","(e)(1)"],"by":{"0":"27, 27"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"0":"16"}},{"t":"usc","label":"29 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/29/204","by":{"0":"16"}},{"t":"usc","label":"29 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/29/211","by":{"0":"29"}},{"t":"usc","label":"29 U.S.C. § 212","url":"https://www.law.cornell.edu/uscode/text/29/212","subs":["(b)"],"by":{"0":"16, 17"}},{"t":"usc","label":"29 U.S.C. § 216","url":"https://www.law.cornell.edu/uscode/text/29/216","subs":["(b)","(c)"],"stext":{"head":"§216. Penalties","paras":[[0,"(a) Fines and imprisonment"],[0,"Any person who willfully violates any of the provisions of section 215 of this title shall upon conviction thereof be subject to a fine of not more than $10,000, or to imprisonment for not more than six months, or both. No person shall be imprisoned under this subsection except for an offense committed after the conviction of such person for a prior offense under this subsection."],[0,"(b) Damages; right of action; attorney's fees and costs; termination of right of action"],[0,"Any employer who violates the provisions of section 206 or section 207 of this title shall be liable to the employee or employees affected in the amount of their unpaid minimum wages, or their unpaid overtime compensation, as the case may be, and in an additional equal amount as liquidated damages. Any employer who violates the provisions of section 215(a)(3) or 218d of this title shall be liable for such legal or equitable relief as may be appropriate to effectuate the purposes of section 215(a)(3) or 218d of this title, including without limitation employment, reinstatement, promotion, and the payment of wages lost and an additional equal amount as liquidated damages. Any employer who violates section 203(m)(2)(B) of this title shall be liable to the employee or employees affected in the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and in an additional equal amount as liquidated damages. An action to recover the liability prescribed in the preceding sentences may be maintained against any employer (including a public agency) in any Federal or State court of competent jurisdiction by any one or more employees for and in behalf of himself or themselves and other employees similarly situated. No employee shall be a party plaintiff to any such action unless he gives his consent in writing to become such a party and such consent is filed in the court in which such action is brought. The court in such action shall, in addition to any judgment awarded to the plaintiff or plaintiffs, allow a reasonable attorney's fee to be paid by the defendant, and costs of the action. The right provided by this subsection to bring an action by or on behalf of any employee, and the right of any employee to become a party plaintiff to any such action, shall terminate upon the filing of a complaint by the Secretary of Labor in an action under section 217 of this title in which (1) restraint is sought of any further delay in the payment of unpaid minimum wages, or the amount of unpaid overtime compensation, as the case may be, owing to such employee under section 206 or section 207 of this title by an employer liable therefor under the provisions of this subsection or (2) legal or equitable relief is sought as a result of alleged violations of section 215(a)(3) or 218d of this title."],[0,"(c) Payment of wages and compensation; waiver of claims; actions by the Secretary; limitation of actions"],[0,"The Secretary is authorized to supervise the payment of the unpaid minimum wages or the unpaid overtime compensation owing to any employee or employees under section 206 or section 207 of this title, and the agreement of any employee to accept such payment shall upon payment in full constitute a waiver by such employee of any right he may have under subsection (b) of this section to such unpaid minimum wages or unpaid overtime compensation and an additional equal amount as liquidated damages. The Secretary may bring an action in any court of competent jurisdiction to recover the amount of unpaid minimum wages or overtime compensation and an equal amount as liquidated damages. The right provided by subsection (b) to bring an action by or on behalf of any employee to recover the liability specified in the first sentence of such subsection and of any employee to become a party plaintiff to any such action shall terminate upon the filing of a complaint by the Secretary in an action under this subsection in which a recovery is sought of unpaid minimum wages or unpaid overtime compensation under sections 206 and 207 of this title or liquidated or other damages provided by this subsection owing to such employee by an employer liable under the provisions of subsection (b), unless such action is dismissed without prejudice on motion of the Secretary. Any sums thus recovered by the Secretary of Labor on behalf of an employee pursuant to this subsection shall be held in a special deposit account and shall be paid, on order of the Secretary of Labor, directly to the employee or employees affected. Any such sums not paid to an employee because of inability to do so within a period of three years shall be covered into the Treasury of the United States as miscellaneous receipts. In determining when an action is commenced by the Secretary of Labor under this subsection for the purposes of the statutes of limitations provided in section 6(a) of the Portal-to-Portal Act of 1947 [29 U.S.C. 255(a)], it shall be considered to be commenced in the case of any individual claimant on the date when the complaint is filed if he is specifically named as a party plaintiff in the complaint, or if his name did not so appear, on the subsequent date on which his name is added as a party plaintiff in such action. The authority and requirements described in this subsection shall apply with respect to a violation of section 203(m)(2)(B) of this title, as appropriate, and the employer shall be liable for the amount of the sum of any tip credit taken by the employer and all such tips unlawfully kept by the employer, and an additional equal amount as liquidated damages."],[0,"(d) Savings provisions"],[0,"In any action or proceeding commenced prior to, on, or after August 8, 1956, no employer shall be subject to any liability or punishment under this chapter or the Portal-to-Portal Act of 1947 [29 U.S.C. 251 et seq.] on account of his failure to comply with any provision or provisions of this chapter or such Act (1) with respect to work heretofore or hereafter performed in a workplace to which the exemption in section 213(f) of this title is applicable, (2) with respect to work performed in Guam, the Canal Zone or Wake Island before the effective date of this amendment of subsection (d), or (3) with respect to work performed in a possession named in section 206(a)(3) 1 of this title at any time prior to the establishment by the Secretary, as provided therein, of a minimum wage rate applicable to such work."],[0,"(e) Civil penalties for certain violations"],[0,"(1)(A) Any person who violates the provisions of sections 2 212 or 213(c) of this title, relating to child labor, or any regulation issued pursuant to such sections, shall be subject to a civil penalty not to exceed—"],[1,"(i) $11,000 for each employee who was the subject of such a violation; or"],[1,"(ii) $50,000 with regard to each such violation that causes the death or serious injury of any employee under the age of 18 years, which penalty may be doubled where the violation is a repeated or willful violation."],[0,"(B) For purposes of subparagraph (A), the term \"serious injury\" means—"],[1,"(i) permanent loss or substantial impairment of one of the senses (sight, hearing, taste, smell, tactile sensation);"],[1,"(ii) permanent loss or substantial impairment of the function of a bodily member, organ, or mental faculty, including the loss of all or part of an arm, leg, foot, hand or other body part; or"],[1,"(iii) permanent paralysis or substantial impairment that causes loss of movement or mobility of an arm, leg, foot, hand or other body part."],[0,"(2) Any person who repeatedly or willfully violates section 206 or 207 of this title, relating to wages, shall be subject to a civil penalty not to exceed $1,100 for each such violation. Any person who violates section 203(m)(2)(B) of this title shall be subject to a civil penalty not to exceed $1,100 for each such violation, as the Secretary determines appropriate, in addition to being liable to the employee or employees affected for all tips unlawfully kept, and an additional equal amount as liquidated damages, as described in subsection (b)."],[0,"(3) In determining the amount of any penalty under this subsection, the appropriateness of such penalty to the size of the business of the person charged and the gravity of the violation shall be considered. The amount of any penalty under this subsection, when finally determined, may be—"],[1,"(A) deducted from any sums owing by the United States to the person charged;"],[1,"(B) recovered in a civil action brought by the Secretary in any court of competent jurisdiction, in which litigation the Secretary shall be represented by the Solicitor of Labor; or"],[1,"(C) ordered by the court, in an action brought for a violation of section 215(a)(4) of this title or a repeated or willful violation of section 215(a)(2) of this title, to be paid to the Secretary."],[0,"(4) Any administrative determination by the Secretary of the amount of any penalty under this subsection shall be final, unless within 15 days after receipt of notice thereof by certified mail the person charged with the violation takes exception to the determination that the violations for which the penalty is imposed occurred, in which event final determination of the penalty shall be made in an administrative proceeding after opportunity for hearing in accordance with section 554 of title 5 and regulations to be promulgated by the Secretary."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/216?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§216. Penalties","tname":"Labor","by":{"0":"1, 24, passim, 1, 16, 17, 18"}},{"t":"usc","label":"29 U.S.C. § 217","url":"https://www.law.cornell.edu/uscode/text/29/217","by":{"0":"17, 18"}},{"t":"law","label":"Pub. L. No. 93-259","url":"https://www.govinfo.gov/link/statute/88/61","by":{"0":"24"}},{"t":"usc","label":"29 U.S.C. § 2617","url":"https://www.law.cornell.edu/uscode/text/29/2617","subs":["(a)(2)"],"by":{"0":"7, 10"}},{"t":"usc","label":"29 U.S.C. § 185","url":"https://www.law.cornell.edu/uscode/text/29/185","by":{"0":"27"}},{"t":"usc","label":"43 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/43/666","by":{"0":"23"}},{"t":"usc","label":"29 U.S.C. § 256","url":"https://www.law.cornell.edu/uscode/text/29/256","by":{"0":"12, 20"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"0":"11"}},{"t":"usc","label":"15 U.S.C. § 77p","url":"https://www.law.cornell.edu/uscode/text/15/77p","subs":["(b)"],"by":{"0":"11"}},{"t":"usc","label":"15 U.S.C. § 77v","url":"https://www.law.cornell.edu/uscode/text/15/77v","subs":["(a)"],"stext":{"head":"§77v. Jurisdiction of offenses and suits","paras":[[0,"(a) Federal and State courts; venue; service of process; review; removal; costs"],[0,"The district courts of the United States and the United States courts of any Territory shall have jurisdiction of offenses and violations under this subchapter and under the rules and regulations promulgated by the Commission in respect thereto, and, concurrent with State and Territorial courts, except as provided in section 77p of this title with respect to covered class actions, of all suits in equity and actions at law brought to enforce any liability or duty created by this subchapter. Any such suit or action may be brought in the district wherein the defendant is found or is an inhabitant or transacts business, or in the district where the offer or sale took place, if the defendant participated therein, and process in such cases may be served in any other district of which the defendant is an inhabitant or wherever the defendant may be found. In any action or proceeding instituted by the Commission under this subchapter in a United States district court for any judicial district, a subpoena issued to compel the attendance of a witness or the production of documents or tangible things (or both) at a hearing or trial may be served at any place within the United States. Rule 45(c)(3)(A)(ii) of the Federal Rules of Civil Procedure shall not apply to a subpoena issued under the preceding sentence. Judgments and decrees so rendered shall be subject to review as provided in sections 1254, 1291, 1292, and 1294 of title 28. Except as provided in section 77p(c) of this title, no case arising under this subchapter and brought in any State court of competent jurisdiction shall be removed to any court of the United States. No costs shall be assessed for or against the Commission in any proceeding under this subchapter brought by or against it in the Supreme Court or such other courts."],[0,"(b) Contumacy or refusal to obey subpena; contempt"],[0,"In case of contumacy or refusal to obey a subpena issued to any person, any of the said United States courts, within the jurisdiction of which said person guilty of contumacy or refusal to obey is found or resides, upon application by the Commission may issue to such person an order requiring such person to appear before the Commission, or one of its examiners designated by it, there to produce documentary evidence if so ordered, or there to give evidence touching the matter in question; and any failure to obey such order of the court may be punished by said court as a contempt thereof."],[0,"(c) Extraterritorial jurisdiction"],[0,"The district courts of the United States and the United States courts of any Territory shall have jurisdiction of an action or proceeding brought or instituted by the Commission or the United States alleging a violation of section 77q(a) of this title involving—"],[1,"(1) conduct within the United States that constitutes significant steps in furtherance of the violation, even if the securities transaction occurs outside the United States and involves only foreign investors; or"],[1,"(2) conduct occurring outside the United States that has a foreseeable substantial effect within the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77v?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§77v. Jurisdiction of offenses and suits","tname":"Commerce and Trade","by":{"0":"8, 14-15"}},{"t":"usc","label":"7 U.S.C. § 2106","url":"https://www.law.cornell.edu/uscode/text/7/2106","subs":["(e)(6)"],"by":{"0":"10"}},{"t":"usc","label":"7 U.S.C. § 2707","url":"https://www.law.cornell.edu/uscode/text/7/2707","subs":["(e)(3)"],"by":{"0":"10"}},{"t":"usc","label":"7 U.S.C. § 3405","url":"https://www.law.cornell.edu/uscode/text/7/3405","subs":["(e)"],"by":{"0":"10"}},{"t":"usc","label":"15 U.S.C. § 78bb","url":"https://www.law.cornell.edu/uscode/text/15/78bb","subs":["(f)(1)"],"by":{"0":"11"}},{"t":"usc","label":"15 U.S.C. § 1719","url":"https://www.law.cornell.edu/uscode/text/15/1719","stext":{"head":"§1719. Jurisdiction of offenses and suits","paras":[[0,"The district courts of the United States, the United States courts of any territory, and the United States District Court for the District of Columbia shall have jurisdiction of offenses and violations under this chapter and under the rules and regulations prescribed by the Director pursuant thereto, and concurrent with State courts, of all suits in equity and actions at law brought to enforce any liability or duty created by this chapter. Any such suit or action may be brought to enforce any liability or duty created by this chapter. Any such suit or action may be brought in the district wherein the defendant is found or is an inhabitant or transacts business, or in the district where the offer or sale took place, if the defendant participated therein, and process in such cases may be served in any other district of which the defendant is an inhabitant or wherever the defendant may be found. Judgments and decrees so rendered shall be subject to review as provided in sections 1254 and 1291 of title 28. No case arising under this chapter and brought in any State court of competent jurisdiction shall be removed to any court of the United States, except where the United States or any officer or employee of the United States in his official capacity is a party. No costs shall be assessed for or against the Director in any proceeding under this chapter brought by or against him in the Supreme Court or such other courts."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1719?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1719. Jurisdiction of offenses and suits","tname":"Commerce and Trade","by":{"0":"15"}},{"t":"usc","label":"15 U.S.C. § 3612","url":"https://www.law.cornell.edu/uscode/text/15/3612","stext":{"head":"§3612. Concurrent State and Federal jurisdiction; venue; removal of cases","paras":[[0,"The district courts of the United States, the United States courts of any territory, and the United States District Court for the District of Columbia shall have jurisdiction under this chapter and, concurrent with State courts, of actions at law or in equity brought under this chapter without regard to the amount in controversy. Any such action may be brought in the district wherein the defendant is found or is an inhabitant or transacts business, or in the district where the sale took place, and process in such cases may be served in other districts of which the defendant is an inhabitant or wherever the defendant may be found. No case arising under this chapter and brought in any State court of competent jurisdiction shall be removed to any court of the United States, except where any officer or employee of the United States in his official capacity is a party."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/3612?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3612. Concurrent State and Federal jurisdiction; venue; removal of cases","tname":"Commerce and Trade","by":{"0":"18"}},{"t":"usc","label":"26 U.S.C. § 7422","url":"https://www.law.cornell.edu/uscode/text/26/7422","subs":["(a)","(b)"],"by":{"0":"11, 11"}},{"t":"usc","label":"29 U.S.C. § 1451","url":"https://www.law.cornell.edu/uscode/text/29/1451","subs":["(a)"],"by":{"0":"11"}},{"t":"usc","label":"43 U.S.C. § 620m","url":"https://www.law.cornell.edu/uscode/text/43/620m","by":{"0":"10"}},{"t":"usc","label":"43 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/43/1551","subs":["(c)"],"by":{"0":"10"}},{"t":"usc","label":"48 U.S.C. § 1421i","url":"https://www.law.cornell.edu/uscode/text/48/1421i","subs":["(h)(2)"],"by":{"0":"11"}},{"t":"reg","label":"29 C.F.R. § 1626.15","url":"https://www.ecfr.gov/current/title-29/section-1626.15","subs":["(a)"],"by":{"0":"16"}}]};